-- Me2U platform foundation. Apply migrations in order; no production schema is mutated manually.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE user_role AS ENUM ('PLATFORM_ADMIN','PLATFORM_OPERATIONS','DISPATCHER','MERCHANT_OWNER','MERCHANT_MANAGER','MERCHANT_STAFF','COURIER','CUSTOMER','COMPLIANCE_REVIEWER','SUPPORT');
CREATE TYPE delivery_state AS ENUM ('REQUESTED','AWAITING_DISPATCH','ASSIGNED','COURIER_EN_ROUTE_TO_PICKUP','ARRIVED_PICKUP','PICKED_UP','IN_TRANSIT','ARRIVED_DROPOFF','VERIFICATION_REQUIRED','DELIVERED','CANCELLED','FAILED','REFUSED','RETURN_REQUIRED','RETURNING','RETURNED');
CREATE TYPE policy_status AS ENUM ('ALLOWED','DISABLED','REQUIRES_REVIEW');
CREATE TABLE organization (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, slug text UNIQUE NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE tenant (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organization(id), name text NOT NULL, slug text UNIQUE NOT NULL, environment text NOT NULL DEFAULT 'development' CHECK (environment IN ('development','staging','production')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE app_user (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), external_auth_id text UNIQUE NOT NULL, email text UNIQUE NOT NULL, display_name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE membership (tenant_id uuid NOT NULL REFERENCES tenant(id), user_id uuid NOT NULL REFERENCES app_user(id), role user_role NOT NULL, PRIMARY KEY (tenant_id,user_id,role));
CREATE TABLE merchant (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant(id), legal_name text NOT NULL, display_name text NOT NULL, eligibility_status policy_status NOT NULL DEFAULT 'REQUIRES_REVIEW', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE merchant_location (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant(id), merchant_id uuid NOT NULL REFERENCES merchant(id), name text NOT NULL, address jsonb NOT NULL, operating_hours jsonb, active boolean NOT NULL DEFAULT true);
CREATE TABLE customer (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant(id), external_ref text, display_name text NOT NULL, contact jsonb NOT NULL DEFAULT '{}');
CREATE TABLE courier (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant(id), user_id uuid NOT NULL REFERENCES app_user(id), status text NOT NULL DEFAULT 'OFFLINE' CHECK(status IN ('OFFLINE','AVAILABLE','BUSY','ON_DELIVERY','PAUSED')), eligibility jsonb NOT NULL DEFAULT '{}');
CREATE TABLE delivery (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant(id), merchant_id uuid REFERENCES merchant(id), merchant_location_id uuid REFERENCES merchant_location(id), customer_id uuid REFERENCES customer(id), external_order_ref text, fulfillment_model text NOT NULL CHECK(fulfillment_model IN ('MERCHANT_HANDOFF','DELIVERY_REQUEST','COURIER_ERRAND')), state delivery_state NOT NULL DEFAULT 'REQUESTED', pickup_address jsonb NOT NULL, dropoff_address jsonb NOT NULL, requested_at timestamptz, verification_required boolean NOT NULL DEFAULT false, verification_passed boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX delivery_tenant_state_idx ON delivery(tenant_id,state,created_at DESC);
CREATE TABLE dispatch_assignment (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant(id), delivery_id uuid NOT NULL REFERENCES delivery(id), courier_id uuid NOT NULL REFERENCES courier(id), assigned_by uuid NOT NULL REFERENCES app_user(id), assigned_at timestamptz NOT NULL DEFAULT now(), unassigned_at timestamptz);
CREATE INDEX active_assignment_idx ON dispatch_assignment(tenant_id,delivery_id) WHERE unassigned_at IS NULL;
CREATE TABLE tracking_session (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant(id), delivery_id uuid NOT NULL REFERENCES delivery(id), courier_id uuid NOT NULL REFERENCES courier(id), device_ref text, started_at timestamptz NOT NULL DEFAULT now(), ended_at timestamptz);
CREATE TABLE location_event (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant(id), delivery_id uuid NOT NULL REFERENCES delivery(id), courier_id uuid NOT NULL REFERENCES courier(id), tracking_session_id uuid REFERENCES tracking_session(id), latitude numeric(9,6) NOT NULL, longitude numeric(9,6) NOT NULL, accuracy_m numeric(8,2), heading numeric(6,2), speed_mps numeric(8,2), recorded_at timestamptz NOT NULL, received_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX location_delivery_time_idx ON location_event(delivery_id,recorded_at DESC);
CREATE TABLE proof_of_delivery (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant(id), delivery_id uuid NOT NULL REFERENCES delivery(id), captured_by uuid NOT NULL REFERENCES app_user(id), media_ref text, recipient_confirmation boolean NOT NULL DEFAULT false, signature_ref text, latitude numeric(9,6), longitude numeric(9,6), verification_result jsonb, notes text, captured_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE regulated_product_category (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text UNIQUE NOT NULL, name text NOT NULL);
CREATE TABLE regulated_delivery_policy (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant(id), merchant_id uuid REFERENCES merchant(id), category_id uuid NOT NULL REFERENCES regulated_product_category(id), jurisdiction text NOT NULL, age_threshold smallint, verification_method text NOT NULL, signature_required boolean NOT NULL DEFAULT false, return_required boolean NOT NULL DEFAULT true, status policy_status NOT NULL DEFAULT 'REQUIRES_REVIEW', effective_from timestamptz NOT NULL DEFAULT now(), effective_to timestamptz);
CREATE TABLE identity_verification (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant(id), delivery_id uuid NOT NULL REFERENCES delivery(id), provider text NOT NULL, provider_reference text, age_threshold smallint, age_verified boolean NOT NULL DEFAULT false, recipient_match boolean NOT NULL DEFAULT false, verified_at timestamptz, expires_at timestamptz, data_classification text NOT NULL DEFAULT 'VERIFICATION_ASSERTION');
CREATE TABLE custody_event (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant(id), delivery_id uuid REFERENCES delivery(id), verification_id uuid REFERENCES identity_verification(id), actor_type text NOT NULL, actor_id uuid, provider text, purpose text NOT NULL, data_classification text NOT NULL, action text NOT NULL, result text, metadata jsonb NOT NULL DEFAULT '{}', occurred_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX custody_tenant_time_idx ON custody_event(tenant_id,occurred_at DESC);
CREATE TABLE delivery_event (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant(id), delivery_id uuid REFERENCES delivery(id), event_type text NOT NULL, actor_id uuid, payload jsonb NOT NULL DEFAULT '{}', occurred_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX event_delivery_time_idx ON delivery_event(delivery_id,occurred_at DESC);
CREATE TABLE money_transaction (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant(id), delivery_id uuid REFERENCES delivery(id), provider text NOT NULL, provider_ref text, currency char(3) NOT NULL DEFAULT 'USD', purchase_amount_cents bigint NOT NULL DEFAULT 0, delivery_fee_cents bigint NOT NULL DEFAULT 0, service_fee_cents bigint NOT NULL DEFAULT 0, platform_fee_cents bigint NOT NULL DEFAULT 0, tip_cents bigint NOT NULL DEFAULT 0, tax_cents bigint NOT NULL DEFAULT 0, merchant_amount_cents bigint NOT NULL DEFAULT 0, courier_amount_cents bigint NOT NULL DEFAULT 0, refund_amount_cents bigint NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE migration (version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
